const bridgeParts = ["bridge-back", "bridge-beam", "bridge-front"].map(part);
const drops = part("drops"), hand = part("hand");
const cells = {}; svg.querySelectorAll("[data-cell]").forEach((el) => { cells[el.dataset.cell] = el; });
const towers = [...svg.querySelectorAll("[data-tower]")], faces = [...svg.querySelectorAll("[data-face]")];
