let test = null, done = null, line = "", runs = 0, handV = 0;
const smooth = (a, b, x) => { const u = Math.min(1, Math.max(0, (x - a) / (b - a))); return u * u * (3 - 2 * u); };
const over = (s, u) => smooth(s[0], s[1], u);
const show = (el, o) => el.setAttribute("opacity", Math.max(0, Math.min(1, o)).toFixed(3));
const put = (el, p) => el.setAttribute("transform", translateAlong(P, p));
function towerD(r, h) {
  const y = C.ROW_Y[r], w = C.TOWER_W;
  return solidSvg(slabOf({ x: C.TOWER_X - w / 2, y: y - w / 2, w, d: w, r: 2 }, 3, Math.max(0.6, h), P, 3, 0.5), { tone: "hi", crease: "lo", className: "dm-tower" });
}
const towerH = [0, 0, 0, 0];
function setTower(r, h) {
  if (Math.abs(towerH[r] - h) < 0.05) return;
  towerH[r] = h; towers[r].innerHTML = towerD(r, h);
  show(faces[r], smooth(3, 8, h));
  faces[r].setAttribute("transform", translateAlong(P, [0, 0, Math.max(0, h - 5)]));
}
function handD(v) {
  const a = v * Math.PI * 2, x = C.DIAL[0], y = C.DIAL[1];
  return lineOnTop([x + Math.sin(a) * 1.6, y - Math.cos(a) * 1.6], [x + Math.sin(a) * (C.DIAL_R - 3), y - Math.cos(a) * (C.DIAL_R - 3)], C.DIAL_Z + 0.1, P);
}
