  if (dv >= 0) { put(drops, [C.COL_X[col], 0, C.NOZ_Z - 4 - (C.NOZ_Z - 4 - C.CELL_Z - 12) * smooth(0, 1, dv)]); show(drops, 1 - smooth(0.8, 1, dv)); }
  else show(drops, 0);
