  const kill = u < 0 ? 0 : over(TL.DIE, u);
  for (let c = 0; c < 6; c++) for (let r = 0; r < 4; r++) setCell(r, c, s ? s.dead[c][r] * kill : 0);
  const rise = u < 0 ? 0 : over(TL.TOWER, u);
